import { NextRequest, NextResponse } from "next/server"
import { createClient } from "@/lib/supabase/server"

// Opens a support session from the one-time token generated by
// POST /api/admin/impersonate. The token is the credential: it is single-use
// and short-lived, and only admins can mint one.
export async function GET(req: NextRequest) {
  const tokenHash = req.nextUrl.searchParams.get("token_hash")
  const origin = req.nextUrl.origin
  if (!tokenHash) return NextResponse.redirect(`${origin}/auth/login`)

  const supabase = await createClient()
  const { data, error } = await supabase.auth.verifyOtp({ token_hash: tokenHash, type: "magiclink" })
  if (error || !data.user) {
    return NextResponse.redirect(`${origin}/auth/login?error=soporte_link_invalido`)
  }

  // Session cookie (no maxAge): dies with the incognito window. Readable by
  // the client so the support banner can show who is being viewed.
  const res = NextResponse.redirect(`${origin}/dashboard`)
  res.cookies.set("soporte_modo", data.user.email ?? "usuario", { path: "/", sameSite: "lax", secure: true })
  return res
}
